entries[71548] = { ["name"] = "Machtwort: Schild", ["text"] = "500 Mana 40 Meter Reichweite\nSofort 15 sek. Abklingzeit\nNutzt die Seelenkraft des Gruppenmitglieds zum Abschirmen und absorbiert dabei 2732 Schaden. Hält 30 Sek. lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 7.5 Sek. lang nicht wieder abgeschirmt werden." }
