entries[71914] = { ["name"] = "Unwiderstehliches Poolpony", ["text"] = "Wirken in 1 sek.\nBlast ein unwiderstehliches Poolpony auf und reitet es." }
entries[71915] = { ["name"] = "Summon Honor's Stand Lumberjack" }
entries[71917] = { ["name"] = "Irresistible Pool Pony: Naga Hatchling Proximity Control - Master" }
