entries[71923] = { ["name"] = "Blutseuche", ["text"] = "Unbegrenzte Reichweite\nSofort\nEine Krankheit, die 12 Sek. lang Schattenschaden verursacht." }
entries[71924] = { ["name"] = "Seuchenstoß", ["text"] = "Nahkampfreichweite\nSofort\nEin bösartiger Schlag, der 60% Waffenschaden plus 24 verursacht und das Ziel mit Blutseuche infiziert, einer Krankheit die im Verlauf der Zeit Schattenschaden verursacht. Der Schlag entfernt einen Effekt, der Heilung über Zeit hervorruft." }
entries[71925] = { ["name"] = "Zerfleischen", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nZerfleischt das Ziel, verursacht 100% des normalen Schadens plus 0.1047 und lässt es 12 Sek. lang 30% zusätzlichen Schaden durch 'Zermalmen', 'Schreddern' und Blutungseffekte erleiden. Gewährt 1 Combopunkt." }
entries[71926] = { ["name"] = "Zerfetzen", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der regelmäßigen Schaden verursacht." }
entries[71927] = { ["name"] = "Schießen", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nBenötigt Distanzwaffe\nSchießt auf einen Gegner und verursacht körperlichen Schaden." }
entries[71928] = { ["name"] = "Feuerball", ["text"] = "40 Meter Reichweite\nWirken in 3 sek.\nFügt einem Gegner Feuerschaden zu." }
entries[71929] = { ["name"] = "Frostnova", ["text"] = "Sofort\nFügt in der Nähe befindlichen Gegnern Frostschaden zu und macht sie bis zu 5 Sek. lang bewegungsunfähig." }
entries[71930] = { ["name"] = "Lichtblitz", ["text"] = "40 Meter Reichweite\nWirken in 1.5 sek.\nRuft heilige Magie an, um einen Verbündeten zu heilen." }
entries[71931] = { ["name"] = "Große Heilung", ["text"] = "40 Meter Reichweite\nWirken in 2.5 sek.\nRuft heilige Magie an, um einen Verbündeten zu heilen." }
entries[71932] = { ["name"] = "Erneuerung", ["text"] = "40 Meter Reichweite\nSofort\nHeilt das Ziel im Verlauf von 15 Sek. um 48." }
entries[71933] = { ["name"] = "Ausweiden", ["text"] = "Nahkampfreichweite\nSofort\nFinishing-Move, der Schaden verursacht." }
entries[71934] = { ["name"] = "Blitzschlag", ["text"] = "30 Meter Reichweite\nWirken in 2.5 sek.\nSchleudert einen Blitz auf das Ziel und fügt ihm 11 Naturschaden zu." }
entries[71935] = { ["name"] = "Gewitter", ["text"] = "Sofort\nIhr ruft einen Blitzschlag hernieder, der allen Feinden im Umkreis von 0 Metern Schaden zufügt. Alle in der Nähe befindlichen Feinde erleiden 9 Naturschaden und werden zurückgestoßen." }
entries[71936] = { ["name"] = "Schattenblitz", ["text"] = "40 Meter Reichweite\nWirken in 3 sek.\nSchleudert einen Blitz aus dunkler Magie auf einen Feind und verursacht Schattenschaden." }
entries[71937] = { ["name"] = "Verderbnis", ["text"] = "30 Meter Reichweite\nSofort\nVerderbt Gegner in der Nähe und fügt ihnen so 24 Sek. lang alle 3 Sek. Schattenschaden zu." }
entries[71938] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort\nGreift das Ziel sofort an und verursacht (Angriffskraft * 238 / 100) Schaden. Zusätzlich stellen die nächsten 0 erfolgreichen Nahkampfangriffe 1.5% der maximalen Gesundheit wieder her. Dieser Effekt hält bis Abbruch an. Der verursachte Schaden basiert auf Eurer Angriffskraft." }
entries[71939] = { ["name"] = "Alptraumwolke" }
entries[71940] = { ["name"] = "Schreckliche Alpträume", ["text"] = "Unbegrenzte Reichweite\nSofort\nLässt das Ziel Alpträume erleiden, die pro Sekunde 1 Naturschaden verursachen. Zusätzlich regeneriert das Ziel alle 3 Sek. 1 Mana. Der Schaden und die Heilung des Ziels werden ebenfalls um 10% erhöht. Bis zu 100-mal stapelbar. Hält 40 Sek. lang an." }
entries[71941] = { ["name"] = "Schreckliche Alpträume", ["text"] = "Unbegrenzte Reichweite\nSofort\nLässt das Ziel Alpträume erleiden, die pro Sekunde 1 Naturschaden verursachen. Zusätzlich regeneriert das Ziel alle 3 Sek. 1 Mana. Der Schaden und die Heilung des Ziels werden ebenfalls um 10% erhöht. Bis zu 100-mal stapelbar. Hält 40 Sek. lang an." }
entries[71943] = { ["name"] = "Schattenresonanz", ["text"] = "Sofort\nBeschwört einen dunklen Kern. Dunkle Kerne nähren sich von ihrer eignen Energie, wodurch sie sich nach gewisser Zeit selbst zerstören." }
entries[71944] = { ["name"] = "Schockvortex", ["text"] = "Sofort\nFügt allen Feinden innerhalb von 12 Metern 51 Schaden zu und stößt sie zurück." }
entries[71945] = { ["name"] = "Schockvortex" }
entries[71946] = { ["name"] = "Alpträume", ["text"] = "Unbegrenzte Reichweite\nSofort\nFügt Valithria Traumwandler pro Sekunde 34 Naturschaden zu." }
entries[71947] = { ["name"] = "Gas Mask Visual (Purple)" }
entries[71948] = { ["name"] = "Schaden kopieren" }
entries[71949] = { ["name"] = "Frenzied Bloodthirst Visual" }
entries[71951] = { ["name"] = "Nekrotischer Stoß", ["text"] = "Nahkampfreichweite\nSofort\nTrifft den Feind mit einer verfluchten Klinge, fügt dem Ziel 21 körperlichen Schaden und eine andauernde Krankheit zu, die die nächste erhaltene Heilung in Höhe von 71 negiert." }
entries[71952] = { ["name"] = "Präsenz der Sinistren" }
entries[71953] = { ["name"] = "Leuchtende Aura", ["text"] = "Sofort\nDer Paladin erglänzt in strahlendem Licht und heilt nahe Verbündete alle 3 Sek. um 3% ihrer maximalen Gesundheit." }
entries[71954] = { ["name"] = "Heiliger Champion", ["text"] = "45 Meter Reichweite\nSofort\nLegt das Ziel als den Champion des Priesters fest und gewährt ihm 30 Min. lang zusätzliche Gesundheit und Schaden." }
entries[71955] = { ["name"] = "Fokussierte Angriffe", ["text"] = "30 Meter Reichweite\nSofort\nSpringt 30 Sek. lang auf den Rücken des Ziels, was das Angriffstempo erhöht, es aber unmöglich macht, ein anderes Ziel anzugreifen." }
entries[71956] = { ["name"] = "Erfrischender Regen", ["text"] = "200 Mana\nKanalisiert (Wirken in 10 sek.)\nRegeneriert 10 Sek. lang alle nahen Gruppenmitglieder alle 2 Sek. um 64. Kanalisiert." }
entries[71960] = { ["name"] = "Heldenhafter Sprung", ["text"] = "Unbegrenzte Reichweite\nSofort\nSpringt durch die Luft und schmettert auf alle Feinde im Umkreis von 8 Metern um das Zielgebiet hinab, verursacht Schaden und betäubt sie 2 Sek. lang." }
entries[71961] = { ["name"] = "Heldenhafter Sprung", ["text"] = "8 - 25 Meter Reichweite\nSofort 45 sek. Abklingzeit\nSpringt durch die Luft und schmettert auf alle Feinde im Umkreis von 8 Metern um das Zielgebiet hinab und betäubt sie 0.1 Sek. lang." }
entries[71965] = { ["name"] = "Regen des Chaos", ["text"] = "50 Meter Reichweite\nKanalisiert (Wirken in 9 sek.)\nLässt einen Schmelzregen niedergehen, der alle Feinde in einem ausgewählten Gebiet verbrennt und ihnen 9 Sek. lang alle 3 Sek. 16 Chaosschaden zufügt." }
entries[71969] = { ["name"] = "Klebrigen Teer abkratzen", ["text"] = "5 Meter Reichweite\nWirken in 1 sek.\nEntfernt den klebrigen Teer von der Leiche eines Teerelementars." }
