entries[71972] = { ["name"] = "Hittin' Ya Effect" }
entries[71973] = { ["name"] = "Schlangenspucken", ["text"] = "20 Meter Reichweite\nWirken in 2.2 sek.\nFügt dem Ziel Feuerschaden zu." }
entries[71974] = { ["name"] = "Schlangenzauberschutz", ["text"] = "7% von Grundmana\nSofort\nBeschwört für 1 Min. ein Totem der Verbrennung mit 5 Gesundheit zu Euren Füßen, das wiederholt einen Feind im Umkreis von 0 Metern angreift und 5 Feuerschaden zufügt." }
entries[71975] = { ["name"] = "Kampfrausch", ["text"] = "26% von Grundmana\nSofort 5 min Abklingzeit\nErhöht das Nahkampf-, Distanzangriffs- und Zaubertempo aller Gruppen- und Schlachtzugsmitglieder um 80%. Hält 1 Min. lang an.\n\nWenn der Effekt endet, werden die Betroffenen erschöpft und können 10 Min. lang nicht mehr von Kampfrausch profitieren." }
